    log_ax = a * tl.extra.libdevice.fast_logf(x) - x - lg
    ax = tl.extra.libdevice.fast_expf(log_ax)

    valid = (a > 0.0) & (x > 0.0) & (a < inf) & (x < inf)
    # the power series needs O(x) terms, so it is the cheaper branch whenever x is
    # small; the continued fraction is kept for large x where the series stalls
    small = (x < (a + 1.0)) | (x < 30.0)
    in_series = valid & small
    in_cf = valid & (~small)

    ser = tl.zeros_like(a)
    cf = tl.zeros_like(a)

    need_s = tl.max(in_series.to(tl.int32)) > 0
    need_c = tl.max(in_cf.to(tl.int32)) > 0

    if need_s:
        inv_a = _fdiv(1.0, a)
        term = inv_a
        acc = inv_a
        ap = a
        i = 0
        more = 1
        while (i < _MAX_SERIES) & (more > 0):
            ap = ap + 1.0
            term = _fdiv(term * x, ap)
            acc = acc + term
            ap = ap + 1.0
            term = _fdiv(term * x, ap)
            acc = acc + term
            ap = ap + 1.0
            term = _fdiv(term * x, ap)
            acc = acc + term
            ap = ap + 1.0
            term = _fdiv(term * x, ap)
            acc = acc + term
            i = i + 4
            active = in_series & (tl.abs(term) > _EPS * tl.abs(acc))
            more = tl.max(active.to(tl.int32))
        ser = ax * acc

    if need_c:
        fpmin = 1e-30
        b = x + 1.0 - a
        c = b * 0.0 + 1.0e30
        d = _fdiv(1.0, b)
        h = d
        n = 1.0
        q0 = ax * h
        i = 0
        more = 1
        while (i < _MAX_CF) & (more > 0):
            an = -n * (n - a)
            b = b + 2.0
            d = an * d + b
            d = tl.where(tl.abs(d) < fpmin, fpmin, d)
            c = b + _fdiv(an, c)
            c = tl.where(tl.abs(c) < fpmin, fpmin, c)
            d = _fdiv(1.0, d)
            h = h * (c * d)
            n = n + 1.0
            an = -n * (n - a)
            b = b + 2.0
            d = an * d + b
            d = tl.where(tl.abs(d) < fpmin, fpmin, d)
            c = b + _fdiv(an, c)
            c = tl.where(tl.abs(c) < fpmin, fpmin, c)
            d = _fdiv(1.0, d)
            h = h * (c * d)
            n = n + 1.0
            an = -n * (n - a)
            b = b + 2.0
            d = an * d + b
            d = tl.where(tl.abs(d) < fpmin, fpmin, d)
            c = b + _fdiv(an, c)
            c = tl.where(tl.abs(c) < fpmin, fpmin, c)
            d = _fdiv(1.0, d)
            h = h * (c * d)
            n = n + 1.0
            an = -n * (n - a)
            b = b + 2.0
            d = an * d + b
            d = tl.where(tl.abs(d) < fpmin, fpmin, d)
            c = b + _fdiv(an, c)
            c = tl.where(tl.abs(c) < fpmin, fpmin, c)
            d = _fdiv(1.0, d)
            h = h * (c * d)
            n = n + 1.0
            i = i + 4
            q1 = ax * h
            active = in_cf & (tl.abs(q1 - q0) > _EPS)
            q0 = q1
            more = tl.max(active.to(tl.int32))
        cf = 1.0 - ax * h

    res = tl.where(in_series, ser, cf)
    res = tl.minimum(tl.maximum(res, 0.0), 1.0)

    # special values (applied after the clamp so a NaN never leaks into a finite slot)
    res = tl.where(x == 0.0, 0.0, res)
    res = tl.where((a == 0.0) & (x > 0.0), 1.0, res)
    res = tl.where((x == inf) & (a < inf), 1.0, res)
    res = tl.where((a == inf) & (x < inf), 0.0, res)
    res = tl.where((a != a) | (x != x), nan, res)
    res = tl.where((a < 0.0) | (x < 0.0), nan, res)
    return res


